-- @d1-verify {"type":"table","name":"search_metadata_authorizations_v1","sqlIncludes":["search_metadata_authorizations_v1"]}
-- @d1-verify {"type":"trigger","name":"search_metadata_insert_guard","sqlIncludes":["search_metadata_insert_guard"]}
-- @d1-verify {"type":"trigger","name":"search_metadata_update_guard","sqlIncludes":["search_metadata_update_guard"]}
-- @d1-verify {"type":"trigger","name":"search_metadata_delete_guard","sqlIncludes":["search_metadata_delete_guard"]}
-- @d1-verify {"type":"table","name":"search_metadata_guards_v1","sqlIncludes":["revision integer","fencing_token integer"]}
CREATE TABLE IF NOT EXISTS search_metadata_guards_v1(article_id TEXT PRIMARY KEY NOT NULL, revision INTEGER NOT NULL, fencing_token INTEGER NOT NULL, document_fingerprint TEXT NOT NULL, fts_fingerprint TEXT NOT NULL, tombstone INTEGER NOT NULL CHECK(tombstone IN(0,1)), updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS search_metadata_authorizations_v1(article_id TEXT PRIMARY KEY NOT NULL,token TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS search_metadata_insert_guard BEFORE INSERT ON search_documents WHEN EXISTS(SELECT 1 FROM search_metadata_guards_v1 WHERE article_id=NEW.article_id) AND NOT EXISTS(SELECT 1 FROM search_metadata_authorizations_v1 WHERE article_id=NEW.article_id) AND NOT EXISTS(SELECT 1 FROM e2e_search_write_authorizations_v1 WHERE article_id=NEW.article_id) BEGIN SELECT RAISE(ABORT,'search_metadata_unguarded_writer'); END;
CREATE TRIGGER IF NOT EXISTS search_metadata_update_guard BEFORE UPDATE ON search_documents WHEN (EXISTS(SELECT 1 FROM search_metadata_guards_v1 WHERE article_id=NEW.article_id) OR EXISTS(SELECT 1 FROM search_metadata_guards_v1 WHERE article_id=OLD.article_id)) AND NOT (EXISTS(SELECT 1 FROM search_metadata_authorizations_v1 WHERE article_id=NEW.article_id) AND EXISTS(SELECT 1 FROM search_metadata_authorizations_v1 WHERE article_id=OLD.article_id)) AND NOT (EXISTS(SELECT 1 FROM e2e_search_write_authorizations_v1 WHERE article_id=NEW.article_id) AND EXISTS(SELECT 1 FROM e2e_search_write_authorizations_v1 WHERE article_id=OLD.article_id)) BEGIN SELECT RAISE(ABORT,'search_metadata_unguarded_writer'); END;
CREATE TRIGGER IF NOT EXISTS search_metadata_delete_guard BEFORE DELETE ON search_documents WHEN EXISTS(SELECT 1 FROM search_metadata_guards_v1 WHERE article_id=OLD.article_id) AND NOT EXISTS(SELECT 1 FROM search_metadata_authorizations_v1 WHERE article_id=OLD.article_id) AND NOT EXISTS(SELECT 1 FROM e2e_search_write_authorizations_v1 WHERE article_id=OLD.article_id) BEGIN SELECT RAISE(ABORT,'search_metadata_unguarded_writer'); END;
